/// `OnUpgrade`, which writes on the copy being upgraded, for every card
/// whose statements the dump matched.
pub fn upgrade(card: EventCard) -> &'static [Change<V>] {
    match card {
        EventCard::Abundance => &[Change::ChangeCost(CostPool::Energy, -1)],
        EventCard::Apotheosis => &[Change::ChangeCost(CostPool::Energy, -1)],
        EventCard::Apparition => &[Change::RemoveKeyword(CardKeyword::Ethereal)],
        EventCard::BrightestFlame => &[
            Change::Raise(CardVar::Energy, 1),
            Change::Raise(CardVar::Cards, 1),
        ],
        EventCard::ByrdSwoop => &[Change::Raise(CardVar::Damage, 4)],
        EventCard::Caltrops => &[Change::Raise(CardVar::ThornsPower, 2)],
        EventCard::Clash => &[Change::Raise(CardVar::Damage, 4)],
        EventCard::Distraction => &[Change::ChangeCost(CostPool::Energy, -1)],
        EventCard::DualWield => &[Change::Raise(CardVar::Cards, 1)],
        EventCard::Enlightenment => &[],
        EventCard::Entrench => &[Change::ChangeCost(CostPool::Energy, -1)],
        EventCard::Exterminate => &[Change::Raise(CardVar::Damage, 1)],
        EventCard::FeedingFrenzy => &[Change::Raise(CardVar::StrengthPower, 2)],
        EventCard::HelloWorld => &[Change::AddKeyword(CardKeyword::Innate)],
        EventCard::MadScienceSapping => &[Change::AddKeyword(CardKeyword::Innate)],
        EventCard::MadScienceViolence => &[Change::AddKeyword(CardKeyword::Innate)],
        EventCard::MadScienceChoking => &[Change::AddKeyword(CardKeyword::Innate)],
        EventCard::MadScienceEnergized => &[Change::AddKeyword(CardKeyword::Innate)],
        EventCard::MadScienceWisdom => &[Change::AddKeyword(CardKeyword::Innate)],
        EventCard::MadScienceChaos => &[Change::AddKeyword(CardKeyword::Innate)],
        EventCard::MadScienceExpertise => &[Change::AddKeyword(CardKeyword::Innate)],
        EventCard::MadScienceCurious => &[Change::AddKeyword(CardKeyword::Innate)],
        EventCard::MadScienceImprovement => &[Change::AddKeyword(CardKeyword::Innate)],
        EventCard::Maul => &[
            Change::Raise(CardVar::Damage, 1),
            Change::Raise(CardVar::Increase, 1),
        ],
        EventCard::Metamorphosis => &[Change::Raise(CardVar::Cards, 2)],
        EventCard::NeowsFury => &[
            Change::Raise(CardVar::Damage, 4),
            Change::Raise(CardVar::Cards, 1),
        ],
        EventCard::Outmaneuver => &[Change::Raise(CardVar::Energy, 1)],
        EventCard::Peck => &[Change::Raise(CardVar::Repeat, 1)],
        EventCard::Rebound => &[Change::Raise(CardVar::Damage, 3)],
        EventCard::Relax => &[
            Change::Raise(CardVar::Block, 2),
            Change::Raise(CardVar::Cards, 1),
            Change::Raise(CardVar::Energy, 1),
        ],
        EventCard::RipAndTear => &[Change::Raise(CardVar::Damage, 2)],
        EventCard::Squash => &[
            Change::Raise(CardVar::Damage, 2),
            Change::Raise(CardVar::VulnerablePower, 1),
        ],
        EventCard::Stack => &[Change::Raise(CardVar::CalculationBase, 3)],
        EventCard::ToricToughness => &[Change::Raise(CardVar::Block, 2)],
        EventCard::Whistle => &[Change::Raise(CardVar::Damage, 11)],
        EventCard::Wish => &[Change::AddKeyword(CardKeyword::Retain)],
    }
}

